    if isinstance(results, list):
        # Check if all elements are lists
        if all(isinstance(item, list) for item in results):
            backend.assessment_results = results
        else:
            # If not all elements are lists, wrap the results in a list
            backend.assessment_results = [results]
    else:
        # If results is not a list, set to empty list
        backend.assessment_results = []

